const fs = require('fs');
const path = require('path');

const slidesDir = '/app/slides';

const theme = {
  primary: "0F172A",
  secondary: "334155",
  accent: "0EA5E9",
  light: "E0F2FE",
  bg: "F8FAFC"
};

const compileJs = `
const pptxgen = require('pptxgenjs');
const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';

const theme = ${JSON.stringify(theme, null, 2)};

for (let i = 1; i <= 8; i++) {
  const num = String(i).padStart(2, '0');
  const slideModule = require(\`./slide-\${num}.js\`);
  slideModule.createSlide(pres, theme);
}

pres.writeFile({ fileName: '/app/output/final_deck.pptx' })
  .then(() => console.log('Presentation created successfully!'))
  .catch(err => console.error('Error writing presentation:', err));
`;

fs.writeFileSync(path.join(slidesDir, 'compile.js'), compileJs);

const slide1 = `
const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'cover', index: 1, title: 'SkillClaw: Let Skills Evolve Collectively with Agentic Evolver' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 5.625, fill: { color: "FFFFFF" } });

  // Hero image as a background element
  slide.addImage({ path: "imgs/figure_1.jpg", x: 5, y: 0, w: 5, h: 5.625, sizing: { type: "cover" } });

  // Overlay gradient or solid shape to make text readable
  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 6.5, h: 5.625, fill: { color: theme.bg } });
  slide.addShape(pres.shapes.RECTANGLE, { x: 6.5, y: 0, w: 1, h: 5.625, fill: { color: theme.bg, transparency: 50 } });

  slide.addText("SkillClaw", {
    x: 0.5, y: 1.2, w: 5.5, h: 0.8,
    fontSize: 44, fontFace: "Arial", color: theme.accent, bold: true
  });

  slide.addText(slideConfig.title.replace("SkillClaw: ", ""), {
    x: 0.5, y: 2.0, w: 5.5, h: 1.5,
    fontSize: 32, fontFace: "Arial", color: theme.primary, bold: true
  });

  slide.addText("Collective Skill Evolution for Multi-User LLM Agent Ecosystems\\narxiv.org/abs/2604.08377", {
    x: 0.5, y: 4.5, w: 5.5, h: 0.8,
    fontSize: 16, fontFace: "Arial", color: theme.secondary
  });

  return slide;
}
module.exports = { createSlide, slideConfig };
`;

