const pptxgen = require("pptxgenjs");
const slideConfig = { type: 'content', index: 2, title: 'Agent Skills Remain Static After Deployment' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Agent Skills Remain Static After Deployment — Users Rediscover Solutions Independently", {
    x: 0.5, y: 0.4, w: 9, h: 0.8,
    fontSize: 24, fontFace: "Arial", color: theme.primary, bold: true
  });

  // Divider
  slide.addShape(pres.shapes.LINE, { x: 0.5, y: 1.2, w: 9, h: 0, line: { color: theme.accent, width: 2 } });

  // Content
  slide.addText([
    { text: "The Problem with Static Skills\\n", options: { bold: true, color: theme.accent, fontSize: 20 } },
    { text: "• Skills are manually installed from a centralized hub and never updated from runtime experience.\\n", options: { fontSize: 18, color: theme.secondary } },
    { text: "• Similar tasks recur across users, but failures and solutions are repeatedly rediscovered.\\n", options: { fontSize: 18, color: theme.secondary } },
    { text: "• The system fails to improve over time, preventing knowledge accumulation.\\n\\n", options: { fontSize: 18, color: theme.secondary } },
    { text: "Limitations of Existing Paradigms\\n", options: { bold: true, color: theme.accent, fontSize: 20 } },
    { text: "• Memory-based methods: Store past trajectories but remain tied to specific instances and fail to generalize.\\n", options: { fontSize: 18, color: theme.secondary } },
    { text: "• Skill-based methods: Compress experience into structured instructions but treat the library as a static resource.", options: { fontSize: 18, color: theme.secondary } }
  ], { x: 0.5, y: 1.5, w: 8.5, h: 3.5, bullet: false, valign: "top" });

  // Page number
  slide.addShape(pres.shapes.OVAL, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent } });
  slide.addText("2", { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle" });

  return slide;
}
module.exports = { createSlide, slideConfig };
`;

